'use strict';

// MODULES //

var tape = require( 'tape' );
var constantFunction = require( '@stdlib/utils/constant-function' );
var Int32Array = require( '@stdlib/array/int32' );
var Float64Array = require( '@stdlib/array/float64' );
var Complex128Array = require( '@stdlib/array/complex128' );
var BooleanArray = require( '@stdlib/array/bool' );
var AccessorArray = require( '@stdlib/array/base/accessor' );
var Complex128 = require( '@stdlib/complex/float64/ctor' );
var isSameComplex128Array = require( '@stdlib/assert/is-same-complex128array' );
var isSameAccessorArray = require( '@stdlib/assert/is-same-accessor-array' );
var isEqualBooleanArray = require( '@stdlib/assert/is-equal-booleanarray' );
var zeros = require( '@stdlib/array/zeros' );
var toFilledBy = require( './../lib/assign.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof toFilledBy, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function copies elements to another array and replaces all elements within a specified range according to a provided callback function (generic)', function test( t ) {
	var expected;
	var actual;
	var out;
	var x;

	x = [ 1, 2, 3, 4 ];

	out = zeros( x.length, 'generic' );
	expected = [ 1, 5, 5, 4 ];
	actual = toFilledBy( x, 1, 3, constantFunction( 5 ), out, 1, 0 );

	t.strictEqual( actual, out, 'returns expected value' );
	t.deepEqual( actual, expected, 'returns expected value' );

	out = zeros( x.length*2, 'generic' );
	expected = [ 1, 0, 5, 0, 5, 0, 4, 0 ];
	actual = toFilledBy( x, 1, 3, constantFunction( 5 ), out, 2, 0 );

	t.strictEqual( actual, out, 'returns expected value' );
	t.deepEqual( actual, expected, 'returns expected value' );

	out = zeros( x.length*2, 'generic' );
	expected = [ 0, 4, 0, 5, 0, 5, 0, 1 ];
	actual = toFilledBy( x, 1, 3, constantFunction( 5 ), out, -2, out.length-1 );

	t.strictEqual( actual, out, 'returns expected value' );
	t.deepEqual( actual, expected, 'returns expected value' );

	t.end();
});

